    const config = loadConfig(
      process.env as Record<string, string>,
      loadMergedSettings(ctx.cwd),
    );
    if (!config.enabled) return;

    try {
      const db = openDatabase(config.dbPath);
      telemetry.setTarget(createBuffer(config, db));
    } catch (err) {
